for file,t in texts.items():
 source=(dist/file).read_text();header=re.search(r'<header.*?</header>',source,re.S)[0];header=header.replace('href="#"','href="../'+file+'"').replace('href="#','href="../'+file+'#').replace('src="assets/','src="../assets/')
 cards=f'''<div class="download-cards"><article><span class="download-number">01</span><h2>{e(t['mac'])}</h2><p>{e(t['macnote'])}</p><a class="button primary" href="{base}VocaLume-4.6.1-arm64.dmg">{e(t['app'])} ↓</a><small>4.6.1 · DMG · 352 MB</small></article><article><span class="download-number">02</span><h2>Chrome / Opera GX</h2><p>{e(t['extnote'])}</p><a class="button primary" href="{base}vocalume-extension.zip">{e(t['ext'])} ↓</a><small>4.6.1 · ZIP · 20 MB</small></article></div>'''
 steps=''.join('<li><p>'+e(x)+'</p>'+('<pre><code>'+e(command)+'</code></pre>' if i==2 else '')+'</li>' for i,x in enumerate(t['steps']))
 html=f'''<!doctype html><html lang="{t['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{e(t['title'])} · VocaLume 4.6.1</title><link rel="icon" href="../assets/vocalume.png"><link rel="stylesheet" href="../style.css"><link rel="stylesheet" href="../mobile.css"><link rel="stylesheet" href="../download.css"></head><body>{header}<main class="download-main wrap" id="main"><p class="eyebrow">VOCALUME · 4.6.1 BETA</p><h1>{e(t['title'])}</h1><p class="download-intro">{e(t['intro'])}</p><p class="download-notice">{e(t['notice'])}</p><p>{e(t['need'])}</p>{cards}<p class="mobile-install-hint">{e(t['help'])}</p><p class="download-limit">{e(t['pending'])}</p><p class="download-warning">{e(t['warning'])}</p><section id="setup"><h2>{e(t['setup'])}</h2><ol class="download-steps">{steps}</ol></section><section><h2>{e(t['video'])}</h2><video controls controlsList="nodownload" playsinline preload="none" aria-label="{e(t['video'])}"><source src="../assets/install-guide-zh.mp4" type="video/mp4"></video><p>{e(t['videonote'])}</p></section><section><h2>{e(t['checks'])}</h2><p>{e(t['checknote'])}</p><a class="button secondary" href="SHA256SUMS.txt">SHA256SUMS.txt ↓</a></section><a class="text-link" href="../{file}">← {e(t['back'])}</a></main><footer class="footer wrap"><a class="brand" href="../{file}">VocaLume</a><p>4.6.1 · Public beta</p></footer><script src="../language.js"></script></body></html>'''
 (out/file).write_text(html)
 source=source.replace('https://github.com/clark970417-eng/VocaLume/releases','download/'+file).replace('https://github.com/clark970417-eng/VocaLume#readme','download/'+file+'#setup')
 (dist/file).write_text(source)
